// emoji-data.ts
// GENERATED DATA — the standard emoji set the picker offers, grouped exactly like
// Telegram Desktop's emoji panel (Ui::Emoji::Section: People, Nature, Food, Activity,
// Travel, Objects, Symbols — with flags at the end of Symbols), in Unicode/CLDR order.
//
// Sources:
//   • https://unicode.org/Public/emoji/15.1/emoji-test.txt — the emoji themselves, their
//     English names and their group order (fully-qualified entries only; skin-tone
//     variants are left out, matching a panel without a tone selector).
//   • https://github.com/unicode-org/cldr-json (cldr-annotations-full, ru) — the Russian
//     search keywords.
//
// Each section's `entries` is one line per emoji: "<emoji>|<english name>|<russian keywords>".
// Kept as flat strings so the whole set costs a couple of splits to parse and stays small
// in the bundle; parseEmojiSections() in emoji.ts turns it into the picker's model.

export interface EmojiSectionData {
    key: string;   // matches the EMOJI_SECTION_* localization keys
    icon: string;  // tab glyph
    entries: string;
}

